SELECT * FROM oa_schedule_event
WHERE deleted = '0'
AND room_id = #{roomId}
AND start_time < #{endTime} AND end_time > #{startTime}

SELECT * FROM oa_schedule_event
WHERE deleted = '0'
AND room_id = #{roomId}
AND event_id != #{excludeEventId}
AND start_time < #{endTime} AND end_time > #{startTime}

SELECT * FROM oa_schedule_event 
WHERE deleted = '0' 
AND start_time < #{endDate} 
AND end_time > #{startDate}
AND (
   creator_id = #{userId} 
   OR attendees LIKE CONCAT('%', #{userId}, '%') 
) 
ORDER BY start_time ASC

SELECT * FROM oa_schedule_event 
WHERE deleted = '0' 
AND room_id = #{roomId} 
AND start_time < #{dayEnd} 
AND end_time > #{dayStart}
ORDER BY start_time ASC

SELECT * FROM oa_schedule_event 
WHERE deleted = '0' 
AND creator_id = #{userId}
AND room_id IS NOT NULL
AND start_time > #{now}
ORDER BY start_time ASC

SELECT * FROM oa_schedule_event 
WHERE deleted = '0' 
AND creator_id = #{userId}
AND room_id IS NOT NULL
AND end_time < #{now}
ORDER BY start_time DESC
